<?php
require_role(['admin','club','entraineur']);$clubId=(int)($u['club_id']??0);$returnPage=$page==='my_swimmers'?'my_swimmers':'swimmers';$base='index.php?page='.$returnPage;$isAdmin=$role==='admin';$canCreate=$isAdmin||($role==='club'&&$clubId>0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){if(!$isAdmin){$q=db()->prepare('SELECT club_id FROM swimmers WHERE id=?');$q->execute([$id]);if((int)$q->fetchColumn()!==$clubId){http_response_code(403);exit('Accès interdit.');}}db()->prepare('DELETE FROM swimmers WHERE id=?')->execute([$id]);flash('Nageur supprimé.');redirect($base);}
 $license=trim($_POST['license_no']??'');$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$birth=$_POST['birth_date']??'';$sex=$_POST['sex']??'';$newClub=$isAdmin?(($_POST['club_id']??'')!==''?(int)$_POST['club_id']:null):$clubId;
 if(!$license||!$first||!$last||!$birth||!in_array($sex,['F','M'],true)){flash('Veuillez vérifier les informations du nageur.','error');redirect($base);}
 try{if($id){$q=db()->prepare('SELECT club_id FROM swimmers WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();if($old===false||(!$isAdmin&&(int)$old!==$clubId)){http_response_code(403);exit('Accès interdit.');}$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE swimmers SET license_no=?,first_name=?,last_name=?,birth_date=?,sex=?,club_id=? WHERE id=?')->execute([$license,$first,$last,$birth,$sex,$newClub,$id]);record_club_membership($pdo,$id,$newClub);$pdo->prepare('UPDATE users SET club_id=? WHERE swimmer_id=?')->execute([$newClub,$id]);$pdo->commit();flash('Profil du nageur modifié.');}else{if(!$canCreate){http_response_code(403);exit('Seuls l’administrateur et le club peuvent créer un nouveau profil nageur depuis cette page.');}$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO swimmers(license_no,first_name,last_name,birth_date,sex,club_id) VALUES(?,?,?,?,?,?)')->execute([$license,$first,$last,$birth,$sex,$newClub]);$sid=(int)$pdo->lastInsertId();if($newClub)record_club_membership($pdo,$sid,$newClub);$pdo->commit();flash('Nageur ajouté.');}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('Enregistrement impossible : numéro de licence déjà utilisé ou données invalides.','error');}redirect($base);}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM swimmers WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();if($edit&&!$isAdmin&&(int)$edit['club_id']!==$clubId){http_response_code(403);exit('Accès interdit.');}}
$sql='SELECT s.*,c.name club FROM swimmers s LEFT JOIN clubs c ON c.id=s.club_id';$args=[];if(!$isAdmin){$sql.=' WHERE s.club_id=?';$args[]=$clubId;}$sql.=' ORDER BY s.last_name,s.first_name';$q=db()->prepare($sql);$q->execute($args);
?>
<?php if($canCreate||$edit):?><section class="panel"><h3><?=$edit?'Modifier le nageur':'Ajouter un nageur'?></h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div><label>Numéro de licence</label><input name="license_no" required value="<?=e($edit['license_no']??'')?>"></div><div><label>Prénom</label><input name="first_name" required value="<?=e($edit['first_name']??'')?>"></div><div><label>Nom</label><input name="last_name" required value="<?=e($edit['last_name']??'')?>"></div><div><label>Date de naissance</label><input type="date" name="birth_date" required value="<?=e($edit['birth_date']??'')?>"></div><div><label>Sexe</label><select name="sex"><option value="F" <?=($edit['sex']??'F')==='F'?'selected':''?>>Féminin</option><option value="M" <?=($edit['sex']??'')==='M'?'selected':''?>>Masculin</option></select></div><?php if($isAdmin):?><div><label>Club actuel</label><select name="club_id"><option value="">Aucun club</option><?php foreach(db()->query('SELECT id,name FROM clubs ORDER BY name') as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['club_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="span2"><button class="btn primary"><?=$edit?'Enregistrer les modifications':'Ajouter le nageur'?></button><?php if($edit):?> <a class="btn light" href="<?=$base?>">Annuler</a><?php endif;?></div></form></section><?php endif;?>
<section class="panel"><h3><?=in_array($role,['club','entraineur'],true)?'Mes nageurs':'Liste des nageurs'?></h3><div class="table-wrap"><table><tr><th>Licence</th><th>Nageur</th><th>Naissance</th><th>Sexe</th><th>Club</th><th>Actions</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['license_no'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['birth_date'])?></td><td><?=e($r['sex'])?></td><td><?=e($r['club']??'—')?></td><td class="actions"><a class="link" href="<?=$base?>&edit=<?=$r['id']?>">Modifier</a><form class="inline" method="post" onsubmit="return confirm('Supprimer ce nageur et ses engagements/résultats ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Supprimer</button></form></td></tr><?php endforeach;?></table></div></section>